import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest cases ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a single plain sword as 105 G (100 G base + 5 G fee)");
  it.todo("quotes a single plain amulet as 65 G (60 G base + 5 G fee)");
  it.todo("quotes a single plain staff as 85 G (80 G base + 5 G fee)");
  it.todo("quotes a single plain potion as 45 G (40 G base + 5 G fee)");

  // --- Components and the building block of 3 alike ---
  it.todo("quotes a single rune as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as 30 G (25 G base + 5 G fee)");
  it.todo("quotes 2 runes as 50 G base premium (no block)");
  it.todo("quotes 3 runes as 60 G base premium (block applies)");
  it.todo("quotes 4 runes as 100 G base premium (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as 175 G base premium (no block -- 7 is not exactly 3)");

  // --- "Alike" means same type, not same family ---
  it.todo("quotes 2 runes + 1 moonstone as 75 G base premium (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones as 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers in isolation ---
  it.todo("adds a 50 % curse surcharge to a cursed sword -- base 100 G becomes 150 G");
  it.todo("adds a 30 % high-enchantment surcharge to a sword with enchantment 5 (threshold, inclusive)");
  it.todo("adds no high-enchantment surcharge to a sword with enchantment 4 (below threshold)");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies only the curse surcharge to a cursed sword with enchantment 4");

  // --- Modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge to the cursed item's base premium only -- cursed sword + plain amulet: 160 G base + 50 G curse = 210 G before further modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount to the policy base premium for a customer with exactly 2 years (threshold, inclusive)");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge to the policy base premium");
  it.todo("applies a 15 % follow-up-contract discount on the customer's second quote in a scenario");
  it.todo("applies no follow-up-contract discount on the customer's first quote in a scenario");
  it.todo("still applies the first-insurance surcharge on a follow-up contract -- each quote's items are treated as a first insurance regardless of customer history");
  it.todo("adds the 5 G processing fee at the very end, after all other modifiers");

  // --- Rounding in the MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years, no previous contract) as 165 G");
  it.todo("quotes a long-standing customer's second contract with a cursed steel sword (enchantment 7, 3 years) as 160 G");

  // --- Insurance sum and cap ---
  it.todo("computes an insurance sum of 1600 G and a cap of 3200 G for a policy covering a sword and an amulet");
  it.todo("computes an insurance sum of 2000 G and a cap of 4000 G for a policy covering two swords");
  it.todo("computes an insurance sum of 1750 G for a policy covering a sword and 3 runes -- the block discount affects the premium only, not the insurance sum");
  it.todo("bases the cap on the unmodified insurance value -- a cursed sword (premium 165 G) still has a cap of 2000 G");

  // --- Claim: standard reimbursement ---
  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with damage 500 G (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for a damaged rune (insurance value 250 G) with damage 200 G -- runes have no enchantment or material, so no special clause applies");

  // --- Claim: high-enchantment clause ---
  it.todo("reimburses damage to an item with enchantment 8 at 50 % -- steel sword, damage 1000 G, payout 400 G (threshold, inclusive)");
  it.todo("reimburses damage to a steel sword with enchantment 9 at 50 % -- damage 1000 G, payout 400 G");

  // --- Claim: dragon material clause ---
  it.todo("fully reimburses damage to a dragon-material sword with enchantment 5 -- damage 800 G, payout 700 G (only the dragon clause applies)");

  // --- Claim: enchantment threshold vs. dragon material ---
  it.todo("applies the 50 % rule when both clauses apply -- dragon-material sword, enchantment 8, damage 1000 G, payout 400 G");
  it.todo("applies the 50 % rule when both clauses apply -- dragon-material sword, enchantment 9, damage 1000 G, payout 400 G");

  // --- Claim: deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item -- dragon attack damages a sword (500 G) and an amulet (300 G), payout 600 G");
  it.todo("treats two {itemType: 'sword'} damage entries as separate damages, each with its own deductible");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays out 1400 G and leaves 600 G remaining cap for the first 1500 G claim against a sword policy (cap 2000 G)");
  it.todo("reduces the second 1500 G claim to the remaining 600 G cap and leaves remainingCap 0 G");

  // --- Claim: rounding in the MHPCO's favour ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favour)");

  // --- Error cases: the CLI exits non-zero and writes a description to stderr ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick): CLI exits non-zero, writes an error description to stderr, and writes no results to stdout");
  it.todo("rejects a claim referencing an item not covered by the policy (amulet damaged when only a sword is insured): CLI exits non-zero and writes an error description to stderr");
  it.todo("rejects a claim referencing a damage entry with an unknown item type: CLI exits non-zero and writes an error description to stderr");
  it.todo("rejects a claim whose damages contain more entries of a type than the policy covers (two sword damages, one sword insured): CLI exits non-zero and the whole claim is rejected");
  it.todo("rejects a claim containing a damage entry with amount -200: CLI exits non-zero and writes an error description to stderr");

  // --- CLI contract ---
  it.todo("reads a scenario JSON from stdin and writes {results: [...]} to stdout with one result per step, in order");
  it.todo("writes {premium} for a quote step and {payout, remainingCap} for a claim step");
  it.todo("processes the schema example (5 years, amulet quote then 200 G amulet claim) producing a premium and a payout/remainingCap pair");
});

